256	// Criterion 2 of NX-08b: an exchange that makes the request fail is replayed and
257	// the verdict is "failed", with a typed cause. The measured failure is the 502 of
258	// the first read after the cut (cut1-catalog-proxy-path--admin): Classify keeps it
259	// out of "refused" (only 401, 403, 404 and 405 are refusals), and the cause is
260	// the registry's own *oci.StatusError, with the Code and the Source Nexus gave.
261	//
262	// Limit: this is the 502 as Nexus sent it after 20 s. DevDesk's client gives up
263	// after 15 s, so against the live bench the same read ends in a deadline (failed,
264	// no StatusError); the fixture cannot replay that, the integration test of
265	// internal/nexusbench measures it.
266	func TestFailedNexusAnswerKeepsItsCause(t *testing.T) {
267		fixtures := cachedOnlyFixtures(t, "cut1-catalog-proxy-path--admin")
268		ex := wantAnswer(t, fixtures[0], proxyCatalogTarget, 502)
269		if got := ex.Header.Get("Content-Type"); got != "application/json" {
270			t.Fatalf("Content-Type of the 502 = %q: the measurement changed", got)
271		}
272	
273		s := fakenexus.New(t, fixtures...)
274		tg := targetFor(s.URL(nexusHTTPPort), "docker-proxy", nexusfixture.Admin)
275		tg.CatalogUnderPrefix = true
276	
277		imgs, partial, err := CatalogSearcher{}.Search(context.Background(), tg, Query{Text: "mirror"})
278		if len(imgs) != 0 || partial {
279			t.Errorf("rows = %v partial = %v, want none", imgs, partial)
280		}
281		out := Classify(err, len(imgs), partial)
282		if out.Verdict != VerdictFailed {
283			t.Fatalf("verdict = %v, want failed (err = %v)", out.Verdict, err)
284		}
285		if out.Partial || out.Skipped {
286			t.Errorf("marks = %+v, want none", out)
287		}
288	
289		var se *oci.StatusError
290		if !errors.As(err, &se) {
291			t.Fatalf("err = %v (%T), want it to wrap a *oci.StatusError", err, err)
292		}
293		if se.Code != 502 || se.Code != ex.Status {
294			t.Errorf("Code = %d, want 502 (the fixture says %d)", se.Code, ex.Status)
295		}
296		if se.Source != oci.SourceRegistry {
297			t.Errorf("Source = %v, want SourceRegistry (the answer came from the registry endpoint, not a token or management one)", se.Source)
298		}
299		for _, other := range []error{ErrUnsupported, ErrPrefixNotInCatalog, ErrQueryTooShort} {
300			if errors.Is(err, other) {
301				t.Errorf("err is %v: the cause is the status, nothing else", other)
302			}
303		}
304		if got := err.Error(); got != "registry returned 502" {
305			t.Errorf("err.Error() = %q, want the message the journal shows without any URL", got)
306		}
307		if h := s.Hits("cut1-catalog-proxy-path--admin"); h != 1 {
308			t.Errorf("Hits = %d, want 1: a 502 is not retried", h)
309		}
310	}
