97			status  int // pinned: what the bench answered
98			query   string
99			want    Verdict
100			rows    []string
101			code    int // the StatusError Code expected when the verdict comes from an error
102		}
103		proxy := []probe{
104			// Control: the upstream reachable. The catalog of a proxy lists what its
105			// upstream holds, mirror/uncached included (it relays _catalog).
106			{"nominal-catalog-proxy-path--admin", nexusfixture.Admin, 200, "mirror", VerdictOK, []string{"docker-proxy/mirror/cached", "docker-proxy/mirror/uncached"}, 0},
107			{"nominal-catalog-proxy-path--pull", nexusfixture.Pull, 200, "mirror", VerdictOK, []string{"docker-proxy/mirror/cached", "docker-proxy/mirror/uncached"}, 0},
108			{"nominal-catalog-proxy-path--anon", nexusfixture.Anonymous, 200, "mirror", VerdictOK, []string{"docker-proxy/mirror/cached", "docker-proxy/mirror/uncached"}, 0},
109			// The first read after the cut: Nexus relays the failure of its upstream as a
110			// 502. Not refused (a 5xx is a failure), whatever the identity would be.
111			{"cut1-catalog-proxy-path--admin", nexusfixture.Admin, 502, "mirror", VerdictFailed, nil, 502},
112			// Once Nexus has auto-blocked the proxy: a 404 whose body says "Remote Auto
113			// Blocked". DevDesk reads no body, a 404 is a refusal: "unsupported or
114			// refused", although the proxy is blocked and holds mirror/cached.
115			{"cut2-catalog-proxy-path--admin", nexusfixture.Admin, 404, "mirror", VerdictRefused, nil, 404},
116			{"cut2-catalog-proxy-path--pull", nexusfixture.Pull, 404, "mirror", VerdictRefused, nil, 404},
117			{"cut2-catalog-proxy-path--anon", nexusfixture.Anonymous, 404, "mirror", VerdictRefused, nil, 404},
118		}
119		for _, p := range proxy {
120			t.Run(p.fixture, func(t *testing.T) {
121				fixtures := cachedOnlyFixtures(t, p.fixture)
122				wantAnswer(t, fixtures[0], proxyCatalogTarget, p.status)
