124				tg := targetFor(s.URL(nexusHTTPPort), "docker-proxy", p.id)
125				tg.CatalogUnderPrefix = true
126	
127				imgs, partial, err := CatalogSearcher{}.Search(context.Background(), tg, Query{Text: p.query})
128				out := Classify(err, len(imgs), partial)
129	
130				if out != (Outcome{Verdict: p.want}) {
131					t.Fatalf("outcome = %+v, want verdict %v alone (err = %v)", out, p.want, err)
132				}
133				var got []string
134				for _, im := range imgs {
135					got = append(got, im.Repo)
136				}
137				if !reflect.DeepEqual(got, p.rows) {
138					t.Errorf("rows = %v, want %v", got, p.rows)
139				}
140				if p.code == 0 {
141					if err != nil {
142						t.Errorf("err = %v, want nil", err)
143					}
144				} else {
145					var se *oci.StatusError
146					if !errors.As(err, &se) || se.Code != p.code || se.Source != oci.SourceRegistry {
147						t.Errorf("err = %v (%T), want *oci.StatusError{%d, SourceRegistry}", err, err, p.code)
148					}
149				}
150				if h := s.Hits(p.fixture); h != 1 {
