16	// DEVDESK-580 (NX-08b, PR3, NX-04): the HEAD of a manifest through docker-proxy
17	// ("is this image pullable"), and the tag list, replayed from the answers MEASURED
18	// on Nexus 3.98.1-01 with the upstream reachable and then cut. A measurement that
19	// contradicts a criterion or the code is pinned as measured, never fixed here (see
20	// docs/measurements/2026-11-20-nexus-cached-only.md).
21	
22	// cachedOnlyFake replays the named fixtures of the cachedonly campaign. A name
23	// that is not embedded fails the test, so a removed fixture cannot leave it vacuous.
24	func cachedOnlyFake(t *testing.T, names ...string) (*fakenexus.Server, []nexusfixture.Fixture) {
25		t.Helper()
26		all, err := nexusfixture.Load("cachedonly")
27		if err != nil {
28			t.Fatalf("Load(cachedonly): %v", err)
29		}
30		var picked []nexusfixture.Fixture
31		for _, n := range names {
32			found := false
33			for _, f := range all {
34				if f.Name == n {
35					picked = append(picked, f)
36					found = true
37				}
38			}
39			if !found {
40				t.Fatalf("the cachedonly campaign has no fixture %q", n)
41			}
42		}
43		return fakenexus.New(t, picked...), picked
44	}
45	
46	// benchDigest is the digest the bench descriptor gives an upstream image: the
47	// dataset is what the bench seeds, so a digest served by Nexus must be this one.
48	func benchDigest(t *testing.T, name, tag string) string {
49		t.Helper()
50		data, err := os.ReadFile(filepath.FromSlash("../nexusbench/descriptor.json"))
51		if err != nil {
52			t.Fatal(err)
53		}
54		var d struct {
55			Dataset []struct {
56				Name, Tag, Digest, Location string
57			} `json:"dataset"`
58		}
59		if err := json.Unmarshal(data, &d); err != nil {
60			t.Fatal(err)
61		}
62		for _, e := range d.Dataset {
63			if e.Name == name && e.Tag == tag && e.Location == "upstream" {
64				return e.Digest
65			}
66		}
67		t.Fatalf("the bench descriptor has no upstream image %s:%s", name, tag)
68		return ""
69	}
