71	// wantExchange pins the recorded request and status of a one-exchange fixture (a
72	// fixture regenerated with another status fails here before any replay hides it).
73	func wantExchange(t *testing.T, f nexusfixture.Fixture, target string, status int) nexusfixture.Exchange {
74		t.Helper()
75		if len(f.Exchanges) != 1 {
76			t.Fatalf("%s: %d exchanges, want 1", f.Name, len(f.Exchanges))
77		}
78		ex := f.Exchanges[0]
79		if ex.Target != target || ex.Status != status {
80			t.Fatalf("%s recorded %s %s -> %d, this test was written for %s -> %d: the measurement changed",
81				f.Name, ex.Method, ex.Target, ex.Status, target, status)
82		}
83		return ex
84	}
