86	func TestManifestDigestOnMeasuredCutUpstream(t *testing.T) {
87		user, pass := fakenexus.User(nexusfixture.Admin), fakenexus.Password
88	
89		cases := []struct {
90			name    string
91			fixture string
92			repo    string
93			target  string
94			status  int
95			// digestOf is the dataset image whose digest must come back ("" = an error).
96			digestOf string
97			effect   string // the "effect:" header of the fixture
98		}{
99			{
100				// Nominal, the upstream reachable: the HEAD of an image the proxy did not
101				// hold is answered (it fetched it) with the digest of the upstream, and
102				// that read cached it (the bench reported dataset: differs after it).
103				name: "nominal, uncached image", fixture: "nominal-zz-head-proxy-mirror-uncached--admin",
104				repo: "docker-proxy/mirror/uncached", target: "/v2/docker-proxy/mirror/uncached/manifests/1.0", status: 200,
105				digestOf: "mirror/uncached", effect: nexusfixture.EffectCaches,
106			},
107			{
108				// Upstream cut, proxy auto-blocked: an image in the cache is still served.
109				name: "cut, cached image", fixture: "cut2-head-proxy-mirror-cached--admin",
110				repo: "docker-proxy/mirror/cached", target: "/v2/docker-proxy/mirror/cached/manifests/1.0", status: 200,
111				digestOf: "mirror/cached", effect: nexusfixture.EffectCaches,
112			},
113			{
114				// Upstream cut: nothing to serve. A 404 with an empty body (a HEAD has none):
115				// DevDesk gets no typed cause, only "registry returned 404 for <repo>:<tag>".
116				name: "cut, uncached image", fixture: "cut2-head-proxy-mirror-uncached--admin",
117				repo: "docker-proxy/mirror/uncached", target: "/v2/docker-proxy/mirror/uncached/manifests/1.0", status: 404,
118				effect: nexusfixture.EffectCaches,
119			},
120		}
121		for _, tc := range cases {
122			t.Run(tc.name, func(t *testing.T) {
123				s, fixtures := cachedOnlyFake(t, tc.fixture)
124				ex := wantExchange(t, fixtures[0], tc.target, tc.status)
125				if ex.Method != "HEAD" {
126					t.Fatalf("%s is a %s, want HEAD", tc.fixture, ex.Method)
127				}
128				if fixtures[0].Meta.Effect != tc.effect {
129					t.Fatalf("%s: effect %q, want %q", tc.fixture, fixtures[0].Meta.Effect, tc.effect)
130				}
131	
132				digest, err := oci.ManifestDigest(s.URL("127.0.0.1:30481"), tc.repo, "1.0", user, pass)
133	
134				if tc.digestOf != "" {
135					want := benchDigest(t, tc.digestOf, "1.0")
136					if err != nil || digest != want {
137						t.Fatalf("ManifestDigest = %q, %v, want %q: the digest of the dataset image %s", digest, err, want, tc.digestOf)
138					}
139					if got := ex.Header.Get("Docker-Content-Digest"); got != want {
140						t.Errorf("the fixture says %q, the dataset %q", got, want)
141					}
142				} else {
143					if err == nil || digest != "" {
144						t.Fatalf("ManifestDigest = %q, %v, want an error", digest, err)
145					}
146					// Measured behavior, not a wish: the HEAD path returns an untyped
147					// error, so NX-04's criterion "typed cause" holds on the catalog and
148					// tags path only. Nobody can errors.As a status out of it today.
149					var se *oci.StatusError
150					if errors.As(err, &se) {
151						t.Errorf("err is now a *oci.StatusError (%v): the HEAD path became typed, update the measurement note", err)
152					}
153					if want := "registry returned 404 for " + tc.repo + ":1.0"; err.Error() != want {
154						t.Errorf("err = %q, want %q", err, want)
155					}
156				}
157				if h := s.Hits(tc.fixture); h != 1 {
158					t.Errorf("Hits(%s) = %d, want 1", tc.fixture, h)
159				}
160			})
161		}
162	}
