164	// ListRegistryTagsContext on the measured tag lists: what the Tags level of the
165	// registry browser reads. With the upstream cut and the proxy blocked, the proxy
166	// refuses the tag list of an image it holds (404, a typed status) while the group
167	// answers 200 with an EMPTY list for the same image (a silent omission, no error).
168	func TestTagsOnMeasuredCutUpstream(t *testing.T) {
169		user, pass := fakenexus.User(nexusfixture.Admin), fakenexus.Password
